INSERT INTO public.government_entities(name)
SELECT n.name
FROM pg_catalog.jsonb_array_elements_text($entity_names$["الإدعاء العام","الأكاديمية السلطانية للإدارة","الأمانة العامة للاحتفالات الوطنية","الأمانة العامة لمجلس المناقصات","الأمانة العامة لمجلس الوزراء","البنك المركزي العماني","اللجنة العمانية لحقوق الانسان","المتحف الوطني","المجلس الأعلى للقضاء","المجلس العماني للاختصاصات الطبية","المدينة الطبية الجامعية","المركز الوطني للاحصاء والمعلومات","المعهد العالي للقضاء","المؤسسة العامة للمناطق الصناعية ( مدائن )","الهيئة العامة للمناطق الاقتصادية الخاصة والمناطق الحرة","الهيئة العمانية للاعتماد الأكاديمي وضمان جودة التعليم","بلدية ظفار","بلدية مسقط","جامعة التقنية والعلوم التطبيقية","جامعة السلطان قابوس","جهاز الاستثمار العماني","جهاز الضرائب","صندوق الحماية الإجتماعية","كلية العلوم الشرعية","مجلس الدولة","مجلس الشورى","محافظة البريمي","محافظة الداخلية","محافظة الظاهرة","محافظة الوسطى","محافظة جنوب الباطنة","محافظة جنوب الشرقية","محافظة شمال الباطنة","محافظة شمال الشرقية","محافظة ظفار","محافظة مسقط","محافظة مسندم","هيئة البيئة","هيئة الخدمات المالية","هيئة الطيران المدني","هيئة الوثائق والمحفوظات الوطنية","هيئة تنظيم الاتصالات","هيئة تنظيم الخدمات العامة","هيئة تنمية المؤسسات الصغيرة والمتوسطة","هيئة حماية المستهلك","وحدة متابعة تنفيذ رؤية عمان 2040","وزارة الاسكان والتخطيط العمراني","وزارة الاوقاف والشؤون الدينية","وزارة الإعلام","وزارة الإقتصاد","وزارة التجارة والصناعة وترويج الاستثمار","وزارة التراث والسياحة","وزارة التربية والتعليم","وزارة التعليم العالي والبحث العلمي والإبتكار","وزارة التنمية الإجتماعية","وزارة الثروة الزراعية والسمكية وموارد المياه","وزارة الثقافة والرياضة والشباب","وزارة الخارجية","وزارة الداخلية","وزارة الصحة","وزارة الطاقة والمعادن","وزارة العدل والشؤون القانونية","وزارة العمل","وزارة المالية","وزارة النقل والاتصالات وتقنية المعلومات","هيئة المشاريع والمناقصات والمحتوى المحلي"]$entity_names$::jsonb) AS n(name)
ON CONFLICT DO NOTHING;

