UPDATE public.government_entities AS e
SET contact_points = (
  SELECT COALESCE(pg_catalog.jsonb_agg(DISTINCT v.contact), '[]'::jsonb)
  FROM (
    SELECT pg_catalog.jsonb_array_elements(
      CASE WHEN pg_catalog.jsonb_typeof(e.contact_points)='array' THEN e.contact_points ELSE '[]'::jsonb END
    ) AS contact
    UNION ALL
    SELECT pg_catalog.jsonb_array_elements(COALESCE(s.contact_points, '[]'::jsonb)) AS contact
  ) AS v
)
FROM pg_catalog.jsonb_to_recordset($entity_contact_seed$[{"name":"المجلس الأعلى للقضاء","contact_points":[{"name":"حمد الهنائي","job_title":"مساعد مدير تطبيق منظومة الإجادة المؤسسية","email":"Hamad_alhinai@outlook.com","phone":"92117576"},{"name":"عصام محمد باعمر","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"Isam.baomar@sjc.gov.om"}]},{"name":"بلدية ظفار","contact_points":[{"name":"أحمد العمري","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"g.e@dm.gov.om","phone":"95594000"},{"name":"محمد كوفان","job_title":"مدير دائرة","email":"m.a.koufan@dhofar.gov.om","phone":"95901225"}]},{"name":"بلدية مسقط","contact_points":[{"name":"عائشة الحارثي","email":"aisha.a.alharthy@mm.gov.om","phone":"95088688"},{"name":"سلطان الشايعي","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"sultan.s.alshayaei@mm.gov.om"}]},{"name":"جامعة التقنية والعلوم التطبيقية","contact_points":[{"name":"وليد العزري","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"waleed.alazri@utas.edu.om"}]},{"name":"جامعة السلطان قابوس","contact_points":[{"name":"راشد ناصر المعمري","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"rashidm@squ.edu.om"},{"name":"إبراهيم الحوسني","job_title":"مساعد مدير تطبيق منظومة الإجادة المؤسسية","email":"ialhosni@squ.edu.om"}]},{"name":"جهاز الضرائب","contact_points":[{"name":"عبدالرحمن الصائغ","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"abdulrahman.adam@taxoman.gov.om"}]},{"name":"محافظة البريمي","contact_points":[{"name":"عبيد الكعبي","email":"osokaabi@bur.gov.om","phone":"97333085"},{"name":"عمر محمود خالد المنذري","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"omkmandhari@bur.gov.om"}]},{"name":"محافظة الداخلية","contact_points":[{"name":"خالد بن عديم بن يوسف السالمي","job_title":"مدير تطبيق منظومة الإجادة المؤسسية","email":"kaysalmi@dg.gov.om"},{"name":"زهرة أمبوسعيدي","job_title":"مساعد مدير تطبيق منظومة الإجادة المؤسسية","email":"zkamusaidi@dg.gov.om"},{"name":"زاهر الفهدي","job_title":"مدير مشروع","em